from database import Basefrom sqlalchemy.orm import Mapped, mapped_column, relationshipfrom sqlalchemy import String, Boolean, ForeignKey, truefrom sqlalchemy.orm import Mapped, mapped_column'''CREATE TABLE esm'''class User(Base): #ers bebar        __tablename__ = "users" #Esme tabel        id : Mapped[int] = mapped_column(        primary_key =True,autoincrement=True)         username: Mapped[str] = mapped_column(        String(50),        nullable=False,        unique=True    )    email: Mapped[str] = mapped_column(        String(255),        nullable=False,        unique=True    )    password_hash: Mapped[str] = mapped_column(        String(255),        nullable=False    )    is_active: Mapped[bool] = mapped_column(        Boolean,        nullable=False,        server_default=true()    )